#!/usr/bin/env python3
"""Real Nextflow parameter publication and cleanup, using only generated bytes."""
import argparse
import base64
import importlib
import json
import os
from pathlib import Path
import sys
from types import ModuleType


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--nextflow-command-file', type=Path, required=True)
    p.add_argument('--outdir', type=Path, required=True)
    args = p.parse_args()
    root = args.outdir.resolve()
    root.mkdir(parents=True, exist_ok=False)
    repo = Path(__file__).resolve().parents[2]
    package = ModuleType('_katana_unified_cleanup_fixture')
    package.__path__ = [str(repo / 'katana_next/flow')]
    sys.modules[package.__name__] = package
    managed = importlib.import_module(package.__name__ + '.managed')
    storage = importlib.import_module(package.__name__ + '.storage')
    prefix = json.loads(args.nextflow_command_file.read_text())
    params = root / 'params.json'
    flags = {f'skip_{name}': True for name in ('network', 'motiftrace', 'motif_binding', 'rbp_identity', 'enrichment', 'mapp')}
    params.write_text(json.dumps({'outdir': str(root / 'delivery'), **flags, 'deg_fdr': .05}))
    parsed = managed.parser().parse_args(['-params-file', str(params), '--deg_fdr', '.01'])
    assert parsed.native_parameters['deg_fdr'] == .01
    fixture = root / 'fixture'
    fixture.mkdir()
    output = root / 'published'
    scope = root / 'owned'
    storage.create_managed_scope(scope, protected_roots=[fixture, output, params])
    def quote(value):
        return "'" + str(value).replace('\\', '\\\\').replace("'", "\\'") + "'"
    encoded = base64.b64encode(json.dumps(parsed.native_parameters).encode()).decode()
    script = fixture / 'main.nf'
    script.write_text("include { KATANA_FLOW_CONFIGURE } from " + quote(repo / 'pipeline/modules/local/flow_control') + "\n" +
        "workflow {\n def request = new groovy.json.JsonSlurper().parseText(new String('" + encoded + "'.decodeBase64()))\n" +
        ' KATANA_FLOW_CONFIGURE(request, [], file(' + quote(repo / 'pipeline/bin/katana_configure.py') + '))\n}\n')
    config = fixture / 'nextflow.config'
    config.write_text('nextflow.enable.dsl = 2\nprocess { executor="local"; cpus=1; memory="128 MB"; time="2 min"\n' +
        'withName: KATANA_FLOW_CONFIGURE { publishDir=[path:' + quote(output) + ',mode:"copy"] }\n}\n')
    os.environ['NXF_OFFLINE'] = 'true'
    with storage.managed_run_lock(scope):
        work = Path(storage.register_stage(scope, 'upstream')['work_root'])
        native = managed._native_phase([*prefix, 'run', str(script), '-ansi-log', 'false'], work, scope, 'upstream')
        flow = output / 'configuration/flow.json'
        template = output / 'configuration/project-template.json'
        assert json.loads(flow.read_text())['parameters']['differential.deg']['fdr'] == .01
        assert template.is_file()
        before = flow.read_bytes()
        def checkpoint(_):
            assert flow.read_bytes() == before and template.is_file()
            return {'status': 'completed', 'configuration': str(flow)}
        storage.cleanup_stage(scope, 'upstream', native_status=native, checkpoint_validator=checkpoint)
        assert not work.exists()
        checkpoint(None)
        # A second native session consumes the *published* settings after the
        # original configuration producer's work has actually been deleted.
        consumer = fixture / 'consume.nf'
        consumer.write_text('nextflow.enable.dsl=2\nprocess READ_CONFIG {\n input:\n path config\n output:\n path "checked.txt"\n script:\n' +
            "'''\npython3 - <<'PY'\nimport json\nfrom pathlib import Path\nassert json.loads(Path('flow.json').read_text())['parameters']['differential.deg']['fdr'] == .01\nPath('checked.txt').write_text('verified')\nPY\n'''\n}\nworkflow { READ_CONFIG(file(" + quote(flow) + ')) }\n')
        down = Path(storage.register_stage(scope, 'downstream')['work_root'])
        downstream = managed._native_phase([*prefix, 'run', str(consumer), '-ansi-log', 'false'], down, scope, 'downstream')
        assert any(p.read_text() == 'verified' for p in down.rglob('checked.txt'))
        storage.cleanup_stage(scope, 'downstream', native_status=downstream, checkpoint_validator=checkpoint)
        assert not down.exists() and params.is_file()
    (root / 'acceptance.json').write_text(json.dumps({'status': 'passed', 'upstream': native, 'downstream': downstream,
        'published_configuration_survived_cleanup': True, 'cli_overrides_parameter_file': True,
        'scope': 'Native configuration and two-session handoff only; no scientific computations or full report acceptance.'}, indent=2))
    print('Native unified-parameter publication and cleanup passed')


if __name__ == '__main__':
    main()
